-- Migration 185: формула человеческим языком в «?» + тексты категории «Клиенты»
-- БД: YC analytics (таблица metrics). Накат с ноутбука:
--   node migrations/run_local.mjs migrations/185_formula_human_clients.sql --db=analytics
--
-- Задача владельца 24.08: «при нажатии на вопросик не только развернуто и
-- подробно как считается, но еще и формула: что в числителе, что в знаменателе,
-- что в скобках». Начали с повторных продаж (категория «Клиенты») — самое сложное.
--
-- ЧТО БЫЛО: у calculated формула автогенерилась из русских имён (норм), у
-- collected «?» показывал тех-строку вида «count_distinct(deal_id) · окно:
-- created_at · фильтры: funnel_type eq repeat» (та самая жалоба «не везде
-- человекочитаемо»), у external формулы не было ВООБЩЕ — а в повторных продажах
-- почти всё external. Плюс 16 свежих метрик без human_description и 7 client_*
-- с одинаковой заглушкой-шаблоном.
--
-- ЧТО СТАЛО: новая колонка metrics.formula_human — ручная формула словами,
-- в UI побеждает автогенерацию (lib/metrics/formulaText.ts). Заполнена для ВСЕХ
-- активных метрик категории «Клиенты» (включая скрытые служебные числители).
-- human_description дописан пустым и переписан заглушкам; хорошие тексты
-- генератора 179 не тронуты. Бэкап всего — metrics_backup_185.

BEGIN;

ALTER TABLE metrics ADD COLUMN IF NOT EXISTS formula_human text;
COMMENT ON COLUMN metrics.formula_human IS
  'Формула человеческим языком для «?» (что в числителе/знаменателе). Пусто → UI строит автоматически (calculated — из имён, collected — из определения).';

CREATE TABLE IF NOT EXISTS metrics_backup_185 AS SELECT * FROM metrics WHERE false;
INSERT INTO metrics_backup_185
  SELECT * FROM metrics WHERE category = 'Клиенты'
    AND NOT EXISTS (SELECT 1 FROM metrics_backup_185);

UPDATE metrics SET formula_human = $mtxt$= число заказчиков с товарной отгрузкой за последние 90 дней до конца периода (в отчёте по периодам — до конца каждой строки)$mtxt$ WHERE id = 'active_clients_90d';
UPDATE metrics SET formula_human = $mtxt$= число РАЗНЫХ заказчиков с товарной отгрузкой в периоде (каждый — один раз)$mtxt$ WHERE id = 'all_clients_delivered';
UPDATE metrics SET formula_human = $mtxt$= среднее по заказчикам периода от числа РАЗНЫХ товарных групп за всю их историю покупок$mtxt$ WHERE id = 'avg_groups_per_client';
UPDATE metrics SET formula_human = $mtxt$= среднее по товарным отгрузкам периода от числа разных товарных групп внутри одной сделки$mtxt$ WHERE id = 'avg_groups_per_order';
UPDATE metrics SET formula_human = $mtxt$= «Заказы (кол-во)» ÷ «Клиенты с отгрузкой (кол-во)»$mtxt$ WHERE id = 'avg_orders_per_client';
UPDATE metrics SET formula_human = $mtxt$= среднее по товарным отгрузкам периода от числа товарных позиций в сделке$mtxt$ WHERE id = 'avg_products_per_order';
UPDATE metrics SET formula_human = $mtxt$= число РАЗНЫХ товарных групп за всю историю клиента (по позициям сделок, сервисные не считаются)$mtxt$ WHERE id = 'client_categories_count';
UPDATE metrics SET formula_human = $mtxt$= «Прошло времени с последнего заказа» ÷ «Обычная частота заказов» × 100. 100 % — молчит ровно свой обычный цикл, 200 % — просрочил два$mtxt$ WHERE id = 'client_churn_risk_pct';
UPDATE metrics SET formula_human = $mtxt$= сегодня − дата последней товарной отгрузки клиента, дни. В отчётах не по клиентам — медиана по клиентам строки$mtxt$ WHERE id = 'client_days_since_last';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) всех товарных отгрузок клиента за всю историю. В отчётах не по клиентам — медиана по клиентам строки$mtxt$ WHERE id = 'client_ltv';
UPDATE metrics SET formula_human = $mtxt$= ( дата последней отгрузки − дата первой отгрузки ) ÷ ( число отгрузок − 1 ), дни. Пусто, если отгрузка одна$mtxt$ WHERE id = 'client_order_frequency_days';
UPDATE metrics SET formula_human = $mtxt$= сумма отгрузок строки ÷ сумма отгрузок всего отчёта × 100$mtxt$ WHERE id = 'client_share_amount_pct';
UPDATE metrics SET formula_human = $mtxt$= клиенты строки ÷ клиенты всего отчёта (строка «Итого») × 100$mtxt$ WHERE id = 'client_share_count_pct';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков, чья ПЕРВАЯ товарная отгрузка попала в период$mtxt$ WHERE id = 'cohort_clients';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) первых отгрузок повторных клиентов когорты$mtxt$ WHERE id = 'cohort_first_revenue';
UPDATE metrics SET formula_human = $mtxt$= «LTV за 180 дней» ÷ «Количество повторных клиентов (2+ заказов)». Пусто, пока окно не прожито$mtxt$ WHERE id = 'cohort_ltv_180';
UPDATE metrics SET formula_human = $mtxt$= «LTV за 30 дней» ÷ «Количество повторных клиентов (2+ заказов)». Пусто, пока окно не прожито$mtxt$ WHERE id = 'cohort_ltv_30';
UPDATE metrics SET formula_human = $mtxt$= «LTV за 360 дней» ÷ «Количество повторных клиентов (2+ заказов)». Пусто, пока окно не прожито$mtxt$ WHERE id = 'cohort_ltv_360';
UPDATE metrics SET formula_human = $mtxt$= «LTV за 60 дней» ÷ «Количество повторных клиентов (2+ заказов)». Пусто, пока окно не прожито$mtxt$ WHERE id = 'cohort_ltv_60';
UPDATE metrics SET formula_human = $mtxt$= «LTV за 90 дней» ÷ «Количество повторных клиентов (2+ заказов)». Пусто, пока окно не прожито$mtxt$ WHERE id = 'cohort_ltv_90';
UPDATE metrics SET formula_human = $mtxt$= «LTV за все время» ÷ «Количество повторных клиентов (2+ заказов)»$mtxt$ WHERE id = 'cohort_ltv_total';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) ВСЕХ товарных отгрузок повторных клиентов когорты за всю историю (включая первую)$mtxt$ WHERE id = 'cohort_ltv_total_revenue';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков когорты (первая отгрузка в периоде), у которых за всю историю ≥ 2 товарных отгрузок$mtxt$ WHERE id = 'cohort_repeat_clients';
UPDATE metrics SET formula_human = $mtxt$= «LTV за все время» ÷ «Выручка первого заказа». Пример: первый заказ 100 тыс., всего миллион — коэффициент 10$mtxt$ WHERE id = 'cohort_repeat_ratio';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) товарных отгрузок повторных клиентов когорты за 180 дней от их ПЕРВОЙ отгрузки, включая её. Пусто, пока окно 180 дней не прожито всей когортой$mtxt$ WHERE id = 'cohort_repeat_revenue_180';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) товарных отгрузок повторных клиентов когорты за 30 дней от их ПЕРВОЙ отгрузки, включая её. Пусто, пока окно 30 дней не прожито всей когортой$mtxt$ WHERE id = 'cohort_repeat_revenue_30';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) товарных отгрузок повторных клиентов когорты за 360 дней от их ПЕРВОЙ отгрузки, включая её. Пусто, пока окно 360 дней не прожито всей когортой$mtxt$ WHERE id = 'cohort_repeat_revenue_360';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) товарных отгрузок повторных клиентов когорты за 60 дней от их ПЕРВОЙ отгрузки, включая её. Пусто, пока окно 60 дней не прожито всей когортой$mtxt$ WHERE id = 'cohort_repeat_revenue_60';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) товарных отгрузок повторных клиентов когорты за 90 дней от их ПЕРВОЙ отгрузки, включая её. Пусто, пока окно 90 дней не прожито всей когортой$mtxt$ WHERE id = 'cohort_repeat_revenue_90';
UPDATE metrics SET formula_human = $mtxt$= «Вернувшихся за 180 дней» ÷ «Клиентов в когорте» × 100. Пусто, пока окно не прожито всей когортой$mtxt$ WHERE id = 'cohort_return_rate_180';
UPDATE metrics SET formula_human = $mtxt$= «Вернувшихся за 30 дней» ÷ «Клиентов в когорте» × 100. Пусто, пока окно не прожито всей когортой$mtxt$ WHERE id = 'cohort_return_rate_30';
UPDATE metrics SET formula_human = $mtxt$= «Вернувшихся за 360 дней» ÷ «Клиентов в когорте» × 100. Пусто, пока окно не прожито всей когортой$mtxt$ WHERE id = 'cohort_return_rate_360';
UPDATE metrics SET formula_human = $mtxt$= «Вернувшихся за 60 дней» ÷ «Клиентов в когорте» × 100. Пусто, пока окно не прожито всей когортой$mtxt$ WHERE id = 'cohort_return_rate_60';
UPDATE metrics SET formula_human = $mtxt$= «Вернувшихся за 90 дней» ÷ «Клиентов в когорте» × 100. Пусто, пока окно не прожито всей когортой$mtxt$ WHERE id = 'cohort_return_rate_90';
UPDATE metrics SET formula_human = $mtxt$= «Повторные клиенты когорты (2+ заказов)» ÷ «Клиентов в когорте» × 100$mtxt$ WHERE id = 'cohort_return_rate_total';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков когорты, чья ВТОРАЯ товарная отгрузка случилась в течение 180 дней от первой$mtxt$ WHERE id = 'cohort_returned_180';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков когорты, чья ВТОРАЯ товарная отгрузка случилась в течение 30 дней от первой$mtxt$ WHERE id = 'cohort_returned_30';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков когорты, чья ВТОРАЯ товарная отгрузка случилась в течение 360 дней от первой$mtxt$ WHERE id = 'cohort_returned_360';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков когорты, чья ВТОРАЯ товарная отгрузка случилась в течение 60 дней от первой$mtxt$ WHERE id = 'cohort_returned_60';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков когорты, чья ВТОРАЯ товарная отгрузка случилась в течение 90 дней от первой$mtxt$ WHERE id = 'cohort_returned_90';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков с отгрузкой в периоде, у которых за всю историю ≥ 2 разных товарных групп (по позициям сделок, сервисные не считаются)$mtxt$ WHERE id = 'complex_clients';
UPDATE metrics SET formula_human = $mtxt$= «Купившие повторно другую категорию» ÷ «Клиенты с отгрузкой» × 100$mtxt$ WHERE id = 'complex_clients_pct';
UPDATE metrics SET formula_human = $mtxt$= «Получили звонок» ÷ «Должны были получить звонок» × 100$mtxt$ WHERE id = 'contactability_pct';
UPDATE metrics SET formula_human = $mtxt$= число товарных отгрузок периода$mtxt$ WHERE id = 'delivered_deals_count';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков, чья ВТОРАЯ товарная отгрузка за всю историю попала в период$mtxt$ WHERE id = 'first_repeat_clients';
UPDATE metrics SET formula_human = $mtxt$= из «должны были получить звонок»: у скольких в эти 14 дней был исходящий состоявшийся звонок по любой их сделке$mtxt$ WHERE id = 'followup_clients_called';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков, у которых в периоде истекло 14 дней после последней отгрузки (и новой отгрузки за эти 14 дней не случилось)$mtxt$ WHERE id = 'followup_clients_due';
UPDATE metrics SET formula_human = $mtxt$= число разных заказчиков, у которых эта группа встречалась среди ПОЗИЦИЙ товарных отгрузок периода («так или иначе»)$mtxt$ WHERE id = 'group_buyers_count';
UPDATE metrics SET formula_human = $mtxt$= медиана( дата последней товарной отгрузки − дата первой заявки клиента ) ÷ 30,44 дня, месяцы$mtxt$ WHERE id = 'median_client_lifetime_months';
UPDATE metrics SET formula_human = $mtxt$= медиана( дата отгрузки − дата создания сделки ) по товарным отгрузкам периода, дни$mtxt$ WHERE id = 'median_cycle_time_days';
UPDATE metrics SET formula_human = $mtxt$= медиана ВСЕХ интервалов между соседними заказами клиентов, дни$mtxt$ WHERE id = 'median_time_between_orders';
UPDATE metrics SET formula_human = $mtxt$= медиана интервалов между заказами, каждый из которых принёс клиенту новую товарную группу, дни$mtxt$ WHERE id = 'median_time_between_orders_diff_cat';
UPDATE metrics SET formula_human = $mtxt$= медиана( дата 2-го заказа − дата 1-го заказа ) по клиентам, дни. Заказ = отгрузки, склеенные в пределах суток$mtxt$ WHERE id = 'median_time_to_2nd';
UPDATE metrics SET formula_human = $mtxt$= медиана( дата 1-го заказа с НОВОЙ для клиента товарной группой − дата 1-го заказа ), дни$mtxt$ WHERE id = 'median_time_to_2nd_diff_cat';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) первых товарных отгрузок заказчиков, впервые купивших в периоде$mtxt$ WHERE id = 'new_clients_amount';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков, чья первая товарная отгрузка за всю историю попала в период$mtxt$ WHERE id = 'new_clients_count';
UPDATE metrics SET formula_human = $mtxt$= «Сумма (Купившие повторно)» ÷ ( «Сумма (Новые клиенты)» + «Сумма (Купившие повторно)» ) × 100$mtxt$ WHERE id = 'repeat_amount_share';
UPDATE metrics SET formula_human = $mtxt$= «Прозвон повторных: сделок со звонком» ÷ «Кол-во сделок (повт.)» × 100$mtxt$ WHERE id = 'repeat_called_share_pct';
UPDATE metrics SET formula_human = $mtxt$= сумма (₽) товарных отгрузок периода, которые НЕ первые в истории своего заказчика$mtxt$ WHERE id = 'repeat_clients_amount';
UPDATE metrics SET formula_human = $mtxt$= число заказчиков, у которых в периоде была НЕ первая (повторная) товарная отгрузка$mtxt$ WHERE id = 'repeat_clients_delivered';
UPDATE metrics SET formula_human = $mtxt$= число сделок повторных воронок, созданных в периоде, по которым есть хотя бы один звонок (любое направление и результат)$mtxt$ WHERE id = 'repeat_deals_called_count';
UPDATE metrics SET formula_human = $mtxt$= число сделок повторных воронок, созданных в периоде и забракованных в течение 1 часа после создания$mtxt$ WHERE id = 'repeat_fast_lost_count';
UPDATE metrics SET formula_human = $mtxt$= «Повторные: отказ в течение часа» ÷ «Кол-во сделок (повт.)» × 100$mtxt$ WHERE id = 'repeat_fast_lost_pct';
UPDATE metrics SET formula_human = $mtxt$= «Купившие повторно» ÷ «Клиенты с отгрузкой» × 100 (новые + повторные = все клиенты периода)$mtxt$ WHERE id = 'repeat_rate_clients';

UPDATE metrics SET human_description = $mtxt$Насколько широко заказчик покупает. Считаем разные товарные группы по ПОЗИЦИЯМ всех его товарных отгрузок за историю: «газобетон + доставка» — это одна группа, доставка не считается. В отчётах не по клиентам — медиана по клиентам строки. Товарная отгрузка — где есть хотя бы одна несервисная позиция: доставка/перевозка, аренда спецтехники, услуги для логистов, служебные позиции и «ошибка» товаром не считаются. Тендерные воронки исключены.$mtxt$ WHERE id = 'client_categories_count';
UPDATE metrics SET human_description = $mtxt$Насколько сильно клиент просрочил свой обычный цикл заказа. 1) Считаем «Прошло времени с последнего заказа» (дни молчания). 2) Считаем «Обычную частоту заказов» (его средний промежуток между заказами). 3) Делим первое на второе и умножаем на 100. 100 % — молчит ровно один свой цикл (норма), 200 % — просрочил два цикла, пора звонить. У клиентов с одной отгрузкой не считается — цикла ещё нет.$mtxt$ WHERE id = 'client_churn_risk_pct';
UPDATE metrics SET human_description = $mtxt$Сколько дней заказчик молчит. Берём последнюю товарную отгрузку клиента за всю историю и считаем дни от неё до сегодня. В отчёте «По клиентам» — значение конкретного клиента; в отчётах по менеджерам/группам/периодам — МЕДИАНА по клиентам строки (типичный клиент, а не среднее, которое задирают долгожители). Товарная отгрузка — где есть хотя бы одна несервисная позиция: доставка/перевозка, аренда спецтехники, услуги для логистов, служебные позиции и «ошибка» товаром не считаются. Тендерные воронки исключены.$mtxt$ WHERE id = 'client_days_since_last';
UPDATE metrics SET human_description = $mtxt$Сколько денег заказчик принёс за всю историю: сумма всех его товарных отгрузок (включая первую). В отчёте «По клиентам» — значение клиента; в остальных разрезах — МЕДИАНА по клиентам строки (не сумма: сумма задваивалась бы между менеджерами, у которых покупал один и тот же клиент). Товарная отгрузка — где есть хотя бы одна несервисная позиция: доставка/перевозка, аренда спецтехники, услуги для логистов, служебные позиции и «ошибка» товаром не считаются. Тендерные воронки исключены.$mtxt$ WHERE id = 'client_ltv';
UPDATE metrics SET human_description = $mtxt$Обычный цикл заказа клиента. Берём его первую и последнюю товарные отгрузки за всю историю и делим интервал между ними на число отгрузок минус один — средний промежуток между заказами. У клиента с одной отгрузкой частоты нет — пусто. В отчётах не по клиентам — медиана по клиентам строки.$mtxt$ WHERE id = 'client_order_frequency_days';
UPDATE metrics SET human_description = $mtxt$Доля строки в сумме товарных отгрузок отчёта: сумма отгрузок строки ÷ сумма по строке «Итого» × 100. В «Итого» всегда 100 %.$mtxt$ WHERE id = 'client_share_amount_pct';
UPDATE metrics SET human_description = $mtxt$Доля строки в клиентской базе отчёта. Пример: у менеджера 5 заказчиков с отгрузкой в периоде, во всём отчёте их 10 — доля 50 %. Знаменатель — строка «Итого» того же отчёта (уникальные заказчики всего среза, без задвоения между менеджерами), поэтому в «Итого» всегда 100 %.$mtxt$ WHERE id = 'client_share_count_pct';
UPDATE metrics SET human_description = $mtxt$Размер когорты. Когорта периода — заказчики, чья ПЕРВАЯ товарная отгрузка за всю историю попала в период: заказчик навсегда принадлежит одной когорте, поэтому месяцы честно сравнимы между собой. Считаем таких заказчиков (каждый — один раз). Товарная отгрузка — где есть хотя бы одна несервисная позиция: доставка/перевозка, аренда спецтехники, услуги для логистов, служебные позиции и «ошибка» товаром не считаются. Тендерные воронки исключены. Это знаменатель всех «% вернувшихся». Совпадает с метрикой «Новые клиенты (кол-во)» — это одна и та же популяция.$mtxt$ WHERE id = 'cohort_clients';
UPDATE metrics SET human_description = $mtxt$Когорта периода — заказчики, чья ПЕРВАЯ товарная отгрузка за всю историю попала в период: заказчик навсегда принадлежит одной когорте, поэтому месяцы честно сравнимы между собой. 1) Считаем заказчиков когорты, вернувшихся за вторым заказом в течение 180 дней от первой отгрузки. 2) Делим на размер когорты («Клиентов в когорте»), умножаем на 100. Пусто, пока окно 180 дней не прожито всей когортой — свежая когорта иначе выглядела бы провалом рядом со старой. Товарная отгрузка — где есть хотя бы одна несервисная позиция: доставка/перевозка, аренда спецтехники, услуги для логистов, служебные позиции и «ошибка» товаром не считаются. Тендерные воронки исключены.$mtxt$ WHERE id = 'cohort_return_rate_180';
