UPDATE metrics SET human_description = $mtxt$Служебный числитель «% вернувшихся 90 дн». Когорта периода — заказчики, чья ПЕРВАЯ товарная отгрузка за всю историю попала в период: заказчик навсегда принадлежит одной когорте, поэтому месяцы честно сравнимы между собой. Считаем заказчиков когорты, чья вторая товарная отгрузка случилась не позднее 90 дней после первой. Пусто, пока окно 90 дней не прожито всей когортой (конец периода + 90 дней ещё не наступил) — иначе свежая когорта выглядела бы провалом.$mtxt$ WHERE id = 'cohort_returned_90';
UPDATE metrics SET human_description = $mtxt$Какую часть автосозданной повторки менеджеры вообще прозванивают. 1) Считаем «Прозвон повторных: сделок со звонком» и «Кол-во сделок (повт.)» — обе по дате СОЗДАНИЯ сделки в периоде, по одним и тем же воронкам. 2) Делим первое на второе и умножаем на 100. Хвост периода слегка занижен: свежим сделкам ещё не успели позвонить. Для ориентира: июль 2026 — 47,3 %.$mtxt$ WHERE id = 'repeat_called_share_pct';
UPDATE metrics SET human_description = $mtxt$Берём сделки воронок повторных продаж, СОЗДАННЫЕ в периоде (такие сделки создаются автоматически при закрытии сделки в «Отгружено»). Считаем те, по которым есть хотя бы один звонок — любого направления и с любым результатом, привязанный именно к этой сделке (звонок по другой сделке того же заказчика не считается). Данные звонков ведутся с 30.03.2026 — за более ранние периоды метрика ложно нулевая.$mtxt$ WHERE id = 'repeat_deals_called_count';
UPDATE metrics SET human_description = $mtxt$Маркер автобраковки: сделки повторных воронок, созданные в периоде и забракованные в течение ЧАСА после создания (дата отказа минус дата создания < 1 ч). Обычно это «создалась — сразу в отказ» без попытки связаться: в июле 2026 из 290 таких сделок звонок был только у 8, причём 210 забракованы в первые 5 минут.$mtxt$ WHERE id = 'repeat_fast_lost_count';
UPDATE metrics SET human_description = $mtxt$Доля автобраковки. 1) Считаем «Повторные: отказ в течение часа» и «Кол-во сделок (повт.)» — обе по дате создания в периоде. 2) Делим первое на второе, умножаем на 100.$mtxt$ WHERE id = 'repeat_fast_lost_pct';

COMMIT;
